006|/**
007| * Generate consistent placeholder images for portfolio projects
008| * This will be used until the client provides actual project images
009| */
010|
011|// Function to generate a placeholder image URL for each project
012|const generatePortfolioImage = (projectName, category) => {
013|  // Select color theme based on project category
014|  let theme;
015|  switch (category.toLowerCase()) {
016|    case 'e-commerce':
017|      theme = 'primary'; // Blue theme
018|      break;
019|    case 'business':
020|      theme = 'accent';  // Purple theme
021|      break;
022|    case 'service':
023|      theme = 'success'; // Green theme
024|      break;
025|    default:
026|      theme = 'secondary'; // Gray theme
027|  }
028|  
029|  // Create a placeholder with project name
030|  return portfolioThumbnailPlaceholder(350, 200, projectName, theme);
031|};
032|
033|// Generate portfolio images for all projects
034|const portfolioImages = {
035|  'portfolio-freshbite.jpg': generatePortfolioImage('FreshBite Kitchen', 'E-commerce'),
036|  'portfolio-techgear.jpg': generatePortfolioImage('TechGear', 'E-commerce'),
037|  'portfolio-bloom.jpg': generatePortfolioImage('Bloom Boutique', 'E-commerce'),
038|  'portfolio-legal.jpg': generatePortfolioImage('Legal Solutions', 'Service'),
039|  'portfolio-fitness.jpg': generatePortfolioImage('Fitness Revolution', 'Service'),
040|  'portfolio-construction.jpg': generatePortfolioImage('BuildRight Construction', 'Business')
041|};
042|
043|// Generate other placeholder images
044|const placeholderImages = {
045|  'hero-image.svg': getPlaceholderByType('hero', { width: 600, height: 400 }),
046|  'mission.svg': getPlaceholderByType('mission', { width: 500, height: 400 }),
047|  'expertise.svg': getPlaceholderByType('expertise', { width: 500, height: 400 }),
048|  'telegram-integration.svg': getPlaceholderByType('telegram', { width: 500, height: 400 }),
049|  'founder.jpg': getPlaceholderByType('team', { width: 300 })
050|};
051|
052|/**
053| * Gets the URL for a placeholder image by its filename
054| * @param {string} filename - The filename to look up
055| * @returns {string} - Data URL for the image
056| */
057|export const getPlaceholderImage = (filename) => {
058|  // First check portfolio images
059|  if (portfolioImages[filename]) {
060|    return portfolioImages[filename];
061|  }
062|  
063|  // Then check other placeholder images
064|  if (placeholderImages[filename]) {
065|    return placeholderImages[filename];
066|  }
067|  
068|  // If not found, return a generic placeholder
069|  return getPlaceholderByType('default', { 
070|    width: 400, 
071|    height: 300, 
072|    text: 'Image Placeholder' 
073|  });
074|};
075|
076|// Export an object that simulates paths to the images
077|// This allows us to use /assets/images/filename in components
078|// but actually serves the placeholder data URLs
079|export const imagePaths = new Proxy({}, {
080|  get: (_, prop) => {
081|    const filename = prop.toString();
082|    // Return the placeholder image data URL
083|    return getPlaceholderImage(filename);
084|  }
085|});
086|
